class Solution {
    long long sum(long long end, long long len) {
        return (2 * end - len + 1) * len / 2;
    }
public:
    long long maximumBooks(vector<int>& books) {
        int n = books.size();
        vector<long long> dp(n);
        vector<int> st;
        long long answer = 0;
        for (int i = 0; i < n; ++i) {
            while (!st.empty() && books[st.back()] >= books[i] - (i - st.back())) st.pop_back();
            int prev = st.empty() ? -1 : st.back();
            long long len = min((long long)books[i], (long long)i - prev);
            dp[i] = sum(books[i], len) + (prev == -1 ? 0 : dp[prev]);
            answer = max(answer, dp[i]);
            st.push_back(i);
        }
        return answer;
    }
};
